#include <stdio.h>
#include <string.h>

#define MAX_STRINGS 64          /* maximum number of strings (excluding program name) */
#define MAX_LEN     1024        /* maximum allowed length of each string (0x400) */

int main(int argc, char *argv[])
{
    /* ---------- error handling ---------- */
    if (argc < 2) {                     /* no strings supplied */
        puts("EMPTY");
        return 0;
    }

    if (argc - 1 > MAX_STRINGS) {       /* too many strings */
        puts("TOO_MANY");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {    /* length check for each argument */
        if ((size_t)strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* ---------- longest common prefix ---------- */
    const char *prefix = argv[1];
    size_t pref_len = strlen(prefix);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < pref_len && prefix[j] == s[j]) {
            ++j;
        }
        pref_len = j;                   /* shrink to the common part */
        if (pref_len == 0)              /* no common prefix any more */
            break;
    }

    /* ---------- output ---------- */
    for (size_t i = 0; i < pref_len; ++i) {
        putc(prefix[i], stdout);
    }
    putc('\n', stdout);                 /* final newline */

    return 0;
}
